     *         a -&gt; a.node("test.b").isEqualTo(3)
     *     );
     * </code>
     */
    @NotNull
    public JsonAssert and(@NotNull JsonAssertion... assertions) {
        Arrays.stream(assertions).forEach(a -> a.doAssert(this));
