                return node.decimalValue();
            }
        },
        BOOLEAN("boolean") {
            public Object getValue(Node node) {
                return node.asBoolean();
            }
        },
        NULL("null") {
            public Object getValue(Node node) {
                return null;
            }
        };

        private final String description;

        NodeType(String description) {
