    73	
    74	    /**
    75	     * AssertJ 3.17 copies the actual iterable to an ArrayList before creating contains failures. Preserve JsonUnit's
    76	     * JsonList in the failure so error messages remain consistent with JSON assertions.
    77	     */
    78	    private static class JsonUnitIterables extends Iterables {
    79	        private final Failures failures = Failures.instance();
    80	
    81	        JsonUnitIterables(Iterables iterables) {
    82	            super(iterables.getComparisonStrategy());
    83	        }
    84	
    85	        @Override
    86	        public void assertContains(AssertionInfo info, Iterable<?> actual, Object[] values) {
    87	            try {
    88	                super.assertContains(info, actual, values);
    89	            } catch (AssertionError error) {
    90	                if (actual instanceof Node.JsonList && values != null) {
    91	                    List<Object> notFound = new ArrayList<>();
    92	                    for (Object value : values) {
    93	                        if (!getComparisonStrategy().iterableContains(actual, value)) {
    94	                            notFound.add(value);
    95	                        }
    96	                    }
    97	                    if (!notFound.isEmpty()) {
    98	                        throw failures.failure(info, shouldContain(actual, values, notFound, getComparisonStrategy()));
    99	                    }
   100	                }
   101	                throw failureWithJsonListName(error, actual);
   102	            }
   103	        }
   104	
   105	        @Override
   106	        public void assertContainsOnly(AssertionInfo info, Iterable<?> actual, Object[] values) {
   107	            preservingJsonListName(actual, () -> super.assertContainsOnly(info, actual, values));
   108	        }
   109	
   110	        @Override
   111	        public void assertContainsExactly(AssertionInfo info, Iterable<?> actual, Object[] values) {
   112	            preservingJsonListName(actual, () -> super.assertContainsExactly(info, actual, values));
   113	        }
   114	
   115	        @Override
   116	        public void assertContainsExactlyInAnyOrder(AssertionInfo info, Iterable<?> actual, Object[] values) {
   117	            preservingJsonListName(actual, () -> super.assertContainsExactlyInAnyOrder(info, actual, values));
   118	        }
   119	
   120	        private void preservingJsonListName(Iterable<?> actual, Assertion assertion) {
   121	            try {
   122	                assertion.run();
   123	            } catch (AssertionError error) {
   124	                throw failureWithJsonListName(error, actual);
   125	            }
   126	        }
   127	
   128	        private AssertionError failureWithJsonListName(AssertionError error, Iterable<?> actual) {
   129	            String message = error.getMessage();
   130	            if (actual instanceof Node.JsonList && message != null && message.contains("Expecting ArrayList:")) {
   131	                AssertionError assertionError = new AssertionError(message.replace("Expecting ArrayList:", "Expecting JsonList:"));
   132	                assertionError.setStackTrace(error.getStackTrace());
   133	                return assertionError;
   134	            }
   135	            return error;
   136	        }
   137	
   138	        private interface Assertion {
   139	            void run();
   140	        }
   141	    }
   142	}
